        diff --git a/arch/arm64/boot/dts/nvidia/tegra186.dtsi b/arch/arm64/boot/dts/nvidia/tegra186.dtsi
index f0bb6ced4976..3fb60f6f3a93 100644
--- a/arch/arm64/boot/dts/nvidia/tegra186.dtsi
+++ b/arch/arm64/boot/dts/nvidia/tegra186.dtsi
@@ -60,6 +60,7 @@ ethernet@2490000 {
 		clock-names = "master_bus", "slave_bus", "rx", "tx", "ptp_ref";
 		resets = <&bpmp TEGRA186_RESET_EQOS>;
 		reset-names = "eqos";
+		iommus = <&smmu TEGRA186_SID_EQOS>;
 		status = "disabled";

 		snps,write-requests = <1>;
@@ -338,6 +339,7 @@ hda@3510000 {
 			 <&bpmp TEGRA186_RESET_HDA2CODEC_2X>;
 		reset-names = "hda", "hda2hdmi", "hda2codec_2x";
 		power-domains = <&bpmp TEGRA186_POWER_DOMAIN_DISP>;
+		iommus = <&smmu TEGRA186_SID_HDA>;
 		status = "disabled";
 	};

@@ -1158,6 +1160,7 @@ cpu@5 {

 	bpmp: bpmp {
 		compatible = "nvidia,tegra186-bpmp";
+		iommus = <&smmu TEGRA186_SID_BPMP>;
 		mboxes = <&hsp_top0 TEGRA_HSP_MBOX_TYPE_DB
 				    TEGRA_HSP_DB_MASTER_BPMP>;
 		shmem = <&cpu_bpmp_tx &cpu_bpmp_rx>;
-- 
2.25.1




        Provide a response strictly in the following format:
        Code statements:
        <text1>
        <text2>
        ...
        <textN>

Code statements:
```dts
+		iommus = <&smmu TEGRA186_SID_EQOS>;
+		iommus = <&smmu TEGRA186_SID_HDA>;
+		iommus = <&smmu TEGRA186_SID_BPMP>;
```

Code statements:
```dts
+		iommus = <&smmu TEGRA186_SID_EQOS>;
+		iommus = <&smmu TEGRA186_SID_HDA>;
+		iommus = <&smmu TEGRA186_SID_BPMP>;
```

The code statements that lead to the bug are:
```c
iommus = <&smmu TEGRA186_SID_EQOS>;
iommus = <&smmu TEGRA186_SID_HDA>;
iommus = <&smmu TEGRA186_SID_BPMP>;
```
Reason:
The devices on Tegra186 were not properly configured with their respective stream IDs in the SMMU, which are necessary for secure operation. The change that disabled bypass mode by default caused these devices to malfunction because they relied on this configuration for proper operation.

The code statements that fix the bug are:
```c
iommus = <&smmu TEGRA186_SID_EQOS>;
iommus = <&smmu TEGRA186_SID_HDA>;
iommus = <&smmu TEGRA186_SID_BPMP>;
```
Reason:
The patch populates the `iommus` property for the affected devices with their respective stream IDs, ensuring that they are correctly configured for secure operation with the SMMU, thus restoring their functionality after the bypass mode was disabled.

